<template><div class="editorial-products min-h-screen bg-[#fffaf7] px-4 py-10 text-slate-900"><div class="mx-auto max-w-6xl"><div class="mb-10 border-b border-rose-200 pb-6"><p class="text-xs font-bold uppercase tracking-[.2em] text-rose-700">02 / {{ t('nav.products') }}</p><h1 class="mt-2 text-4xl font-black">{{ t('nav.products') }}</h1></div><div v-if="loading" class="text-center py-16">...</div><div v-else class="grid gap-5 md:grid-cols-2"> <ProductCard v-for="(p,i) in products" :key="p.id" :product="p" :index="i" @click="go(p.slug)" @quick-buy="quickBuy" /></div><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { useProductList } from '../../composables/useProductList'; import ProductCard from '../../components/ProductCard.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const router=useRouter(); const {loading,products,initialize,cleanup}=useProductList({pageSize:12,homeRouteName:'products'}); const selected=ref<any>(null); const quickVisible=ref(false); const go=(s:string)=>router.push(`/products/${s}`); const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true}; onMounted(()=>void initialize()); import { onUnmounted } from 'vue'; onUnmounted(cleanup)</script>
